// Parse WaSender webhook payload
const body = $input.first().json.body || $input.first().json;
const rawFrom = (body.from || body.sender || body.phone || '').toString().replace(/[^0-9+]/g, '');
const from = rawFrom.startsWith('+') ? rawFrom : '+' + rawFrom;
const text = (body.text || body.message || body.content || '').toString().trim();
const messageId = body.messageId || body.id || ('M' + Date.now());
const lang = from.startsWith('+44') || from.startsWith('+1') ? 'EN' : 'FR';
return [{ json: { from, text, messageId, lang, received_at: new Date().toISOString() } }];

// Merger les data du lead avec celles du message entrant
const lead = $input.first().json;
const incoming = $('Code — Parse Incoming').item.json;
const safeLead = lead.lead_id ? lead : {
  lead_id: 'L' + new Date().toISOString().replace(/[-:T.]/g, '').slice(0, 14) + '-NOMATCH',
  prenom: 'Bonjour',
  nom: '',
  telephone: incoming.from,
  etat_conversation: 'new',
  notes: ''
};
return [{ json: { lead: safeLead, incoming, etat: safeLead.etat_conversation || 'new' } }];

