// Parse Claude response
const response = $input.first().json;
const rawText = response.content?.[0]?.text || '';
let parsed;
try { parsed = JSON.parse(rawText); } catch (e) { parsed = { intent: 'out_of_context', confidence: 'low' }; }
const merged = $('Code — Merge Lead + Incoming').item.json;
return [{ json: { ...parsed, lead: merged.lead, incoming: merged.incoming } }];

